# Java Configuration Manager
public class ConfigManager {
    private static ConfigManager instance;
    private Config config;

    private ConfigManager() {
        loadConfiguration();
    }

    public static ConfigManager getInstance() {
        if (instance == null) {
            synchronized (ConfigManager.class) {
                if (instance == null) {
                    instance = new ConfigManager();
                }
            }
        }
        return instance;
    }

    private void loadConfiguration() {
        String environment = System.getProperty("env", "dev");
        String configFile = "config/application-" + environment + ".yaml";

        try {
            Yaml yaml = new Yaml(new Constructor(Config.class));
            InputStream inputStream = getClass().getClassLoader()
                .getResourceAsStream(configFile);
            config = yaml.load(inputStream);

            // Validate configuration
            validateConfig();

        } catch (Exception e) {
            throw new RuntimeException("Failed to load configuration: " + configFile, e);
        }
    }

    public String getBaseUrl() {
        return config.getEnvironments().get(getEnvironment()).getBaseUrl();
    }

    public String getBrowser() {
        return System.getProperty("browser", config.getBrowser().getDefault());
    }

    // ... other getter methods
}

// Thread-safe Driver Factory
public class DriverFactory {
    private static ThreadLocal<WebDriver> driverThreadLocal = new ThreadLocal<>();

    public static WebDriver createDriver(String browser) {
        WebDriver driver;
        switch (browser.toLowerCase()) {
            case "chrome":
                driver = createChromeDriver();
                break;
            case "firefox":
                driver = createFirefoxDriver();
                break;
            default:
                throw new IllegalArgumentException("Unsupported browser: " + browser);
        }

        driverThreadLocal.set(driver);
        return driver;
    }

    public static WebDriver getDriver() {
        return driverThreadLocal.get();
    }

    public static void quitDriver(WebDriver driver) {
        if (driver != null) {
            driver.quit();
            driverThreadLocal.remove();
        }
    }

    private static WebDriver createChromeDriver() {
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--start-maximized");
        options.addArguments("--disable-notifications");

        if (ConfigManager.getInstance().isHeadless()) {
            options.addArguments("--headless");
        }

        return new ChromeDriver(options);
    }
}

// Custom Test Listener
public class FrameworkTestListener implements ITestListener {

    @Override
    public void onTestStart(ITestResult result) {
        Logger logger = LoggerFactory.getLogger(result.getTestClass().getName());
        logger.info("Test Started: " + result.getName());

        // Start timer
        result.setAttribute("startTime", System.currentTimeMillis());
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        long executionTime = System.currentTimeMillis() - 
            (Long) result.getAttribute("startTime");

        Logger logger = LoggerFactory.getLogger(result.getTestClass().getName());
        logger.info("Test Passed: " + result.getName() + 
                   " | Execution Time: " + executionTime + "ms");

        // Report to external systems
        ReportManager.recordTestResult(result, "PASS", executionTime);
    }

    @Override
    public void onTestFailure(ITestResult result) {
        WebDriver driver = DriverFactory.getDriver();
        if (driver != null) {
            ScreenshotUtil.captureScreenshot(driver, result.getName());
        }

        Logger logger = LoggerFactory.getLogger(result.getTestClass().getName());
        logger.error("Test Failed: " + result.getName(), result.getThrowable());

        ReportManager.recordTestResult(result, "FAIL", 0);
    }
}

// Retry Mechanism
public class RetryAnalyzer implements IRetryAnalyzer {
    private int retryCount = 0;
    private static final int MAX_RETRY_COUNT = 3;

    @Override
    public boolean retry(ITestResult result) {
        if (retryCount < MAX_RETRY_COUNT) {
            retryCount++;
            LoggerFactory.getLogger(result.getTestClass().getName())
                .info("Retrying test " + result.getName() + 
                     ", attempt " + (retryCount + 1));
            return true;
        }
        return false;
    }
}

// Base Pattern Interface
public interface AutomationPattern {

    /**
     * Initialize pattern with configuration
     * @param config Pattern configuration
     */
    void initialize(PatternConfig config);

    /**
     * Execute pattern-specific behavior
     * @param context Execution context
     * @return Execution result
     */
    PatternResult execute(PatternContext context);

    /**
     * Clean up pattern resources
     */
    void cleanup();

    /**
     * Validate pattern configuration
     * @return Validation result
     */
    PatternValidationResult validate();
}

// Pattern Configuration
public class PatternConfig {
    private String patternName;
    private Map<String, Object> parameters;
    private Class<? extends AutomationPattern> patternClass;
    private List<String> dependencies;

    public PatternConfig(String patternName, 
                        Class<? extends AutomationPattern> patternClass) {
        this.patternName = patternName;
        this.patternClass = patternClass;
        this.parameters = new HashMap<>();
        this.dependencies = new ArrayList<>();
    }

    public void addParameter(String key, Object value) {
        parameters.put(key, value);
    }

    public Object getParameter(String key) {
        return parameters.get(key);
    }

    // Getters and setters
    public String getPatternName() { return patternName; }
    public Map<String, Object> getParameters() { return parameters; }
    public Class<? extends AutomationPattern> getPatternClass() { return patternClass; }
    public List<String> getDependencies() { return dependencies; }
}

// Pattern Registry
public class PatternRegistry {

    private static final Map<String, PatternConfig> registeredPatterns = new HashMap<>();

    static {
        // Register core patterns
        registerPattern("page-object", new PatternConfig("page-object", 
            PageObjectPattern.class));
        registerPattern("factory", new PatternConfig("factory", 
            FactoryPattern.class));
        registerPattern("builder", new PatternConfig("builder", 
            BuilderPattern.class));
        registerPattern("singleton", new PatternConfig("singleton", 
            SingletonPattern.class));
        registerPattern("strategy", new PatternConfig("strategy", 
            StrategyPattern.class));
    }

    public static void registerPattern(String key, PatternConfig config) {
        registeredPatterns.put(key, config);
    }

    public static PatternConfig getPattern(String key) {
        PatternConfig config = registeredPatterns.get(key);
        if (config == null) {
            throw new IllegalArgumentException("Pattern not found: " + key);
        }
        return config;
    }

    public static AutomationPattern createPattern(String key) {
        PatternConfig config = getPattern(key);
        try {
            return config.getPatternClass().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Failed to create pattern: " + key, e);
        }
    }
}

// Pattern-Based Test Base
public abstract class PatternBasedTest {

    protected PatternManager patternManager;
    protected Map<String, AutomationPattern> activePatterns;

    @BeforeSuite
    public void initializePatterns() {
        patternManager = new PatternManager();
        activePatterns = new HashMap<>();

        // Load pattern configuration
        List<PatternConfig> patternConfigs = loadPatternConfigs();

        // Initialize patterns
        for (PatternConfig config : patternConfigs) {
            AutomationPattern pattern = patternManager.createPattern(config);
            pattern.initialize(config);

            // Validate pattern
            PatternValidationResult validation = pattern.validate();
            if (!validation.isValid()) {
                throw new PatternException("Pattern validation failed for " + 
                    config.getPatternName() + ": " + validation.getErrors());
            }

            activePatterns.put(config.getPatternName(), pattern);
        }
    }

    @AfterSuite
    public void cleanupPatterns() {
        for (AutomationPattern pattern : activePatterns.values()) {
            try {
                pattern.cleanup();
            } catch (Exception e) {
                // Log but continue cleanup
                System.err.println("Failed to cleanup pattern: " + e.getMessage());
            }
        }
    }

    protected <T extends AutomationPattern> T getPattern(Class<T> patternType) {
        return activePatterns.values().stream()
            .filter(patternType::isInstance)
            .map(patternType::cast)
            .findFirst()
            .orElseThrow(() -> new PatternException("Pattern not found: " + patternType.getSimpleName()));
    }

    protected abstract List<PatternConfig> loadPatternConfigs();
}

// Driver Factory with Singleton and Factory Patterns
public class DriverFactory {

    private static DriverFactory instance;
    private final ThreadLocal<WebDriver> driverThreadLocal;
    private final BrowserConfig browserConfig;

    private DriverFactory() {
        this.driverThreadLocal = new ThreadLocal<>();
        this.browserConfig = ConfigurationManager.getInstance().getBrowserConfig();
    }

    public static synchronized DriverFactory getInstance() {
        if (instance == null) {
            instance = new DriverFactory();
        }
        return instance;
    }

    public WebDriver getDriver() {
        WebDriver driver = driverThreadLocal.get();
        if (driver == null) {
            driver = createDriver();
            driverThreadLocal.set(driver);
        }
        return driver;
    }

    private WebDriver createDriver() {
        BrowserType browserType = browserConfig.getBrowserType();

        switch (browserType) {
            case CHROME:
                return createChromeDriver();
            case FIREFOX:
                return createFirefoxDriver();
            case EDGE:
                return createEdgeDriver();
            case SAFARI:
                return createSafariDriver();
            case REMOTE:
                return createRemoteDriver();
            default:
                throw new IllegalArgumentException("Unsupported browser: " + browserType);
        }
    }

    private WebDriver createChromeDriver() {
        ChromeOptions options = new ChromeOptions();

        // Add arguments from configuration
        browserConfig.getChromeArguments().forEach(options::addArguments);

        // Set preferences
        options.setExperimentalOption("prefs", browserConfig.getChromePreferences());

        // Set capabilities
        options.setCapability("goog:loggingPrefs", browserConfig.getLoggingPreferences());

        return new ChromeDriver(options);
    }

    public void quitDriver() {
        WebDriver driver = driverThreadLocal.get();
        if (driver != null) {
            try {
                driver.quit();
            } catch (Exception e) {
                // Log but continue
                System.err.println("Error quitting driver: " + e.getMessage());
            }
            driverThreadLocal.remove();
        }
    }

    public void quitAllDrivers() {
        quitDriver();
        instance = null;
    }
}

// Page Object Factory with Prototype Pattern
public class PageFactory {

    private final Map<Class<? extends BasePage>, BasePage> pagePrototypes;
    private final WebDriver driver;

    public PageFactory(WebDriver driver) {
        this.driver = driver;
        this.pagePrototypes = new HashMap<>();
        initializePrototypes();
    }

    private void initializePrototypes() {
        // Register page prototypes
        registerPrototype(LoginPage.class, new LoginPage(driver));
        registerPrototype(HomePage.class, new HomePage(driver));
        registerPrototype(ProductPage.class, new ProductPage(driver));
        registerPrototype(CartPage.class, new CartPage(driver));
        registerPrototype(CheckoutPage.class, new CheckoutPage(driver));
    }

    private void registerPrototype(Class<? extends BasePage> pageClass, 
                                  BasePage prototype) {
        pagePrototypes.put(pageClass, prototype);
    }

    @SuppressWarnings("unchecked")
    public <T extends BasePage> T createPage(Class<T> pageClass) {
        BasePage prototype = pagePrototypes.get(pageClass);
        if (prototype == null) {
            throw new IllegalArgumentException("Page prototype not found: " + pageClass);
        }

        try {
            // Clone the prototype
            T page = (T) prototype.clone();

            // Initialize the cloned page
            page.initialize();

            return page;
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException("Failed to clone page: " + pageClass, e);
        }
    }

    public <T extends BasePage> T getCurrentPage(Class<T> expectedPageClass) {
        // Check if current URL matches expected page
        String currentUrl = driver.getCurrentUrl();

        for (BasePage prototype : pagePrototypes.values()) {
            if (prototype.getClass() == expectedPageClass && 
                prototype.isAt(currentUrl)) {
                return createPage(expectedPageClass);
            }
        }

        throw new IllegalStateException("Not on expected page: " + expectedPageClass + 
                                       ". Current URL: " + currentUrl);
    }
}

// Test Data Builder Pattern
public class UserBuilder {

    private String username;
    private String email;
    private String password;
    private UserRole role;
    private String firstName;
    private String lastName;
    private String phone;
    private Address address;
    private Map<String, Object> additionalAttributes;

    public UserBuilder() {
        this.additionalAttributes = new HashMap<>();
        // Set defaults
        this.role = UserRole.USER;
        this.password = generateDefaultPassword();
    }

    public UserBuilder withUsername(String username) {
        this.username = username;
        return this;
    }

    public UserBuilder withEmail(String email) {
        this.email = email;
        return this;
    }

    public UserBuilder withPassword(String password) {
        this.password = password;
        return this;
    }

    public UserBuilder withRole(UserRole role) {
        this.role = role;
        return this;
    }

    public UserBuilder withName(String firstName, String lastName) {
        this.firstName = firstName;
        this.lastName = lastName;
        return this;
    }

    public UserBuilder withPhone(String phone) {
        this.phone = phone;
        return this;
    }

    public UserBuilder withAddress(Address address) {
        this.address = address;
        return this;
    }

    public UserBuilder withAttribute(String key, Object value) {
        this.additionalAttributes.put(key, value);
        return this;
    }

    public UserTestData build() {
        validate();

        UserTestData user = new UserTestData();
        user.setUsername(username);
        user.setEmail(email);
        user.setPassword(password);
        user.setRole(role);
        user.setFirstName(firstName);
        user.setLastName(lastName);
        user.setPhone(phone);
        user.setAddress(address);
        user.setAdditionalAttributes(additionalAttributes);

        return user;
    }

    private void validate() {
        List<String> errors = new ArrayList<>();

        if (username == null || username.trim().isEmpty()) {
            errors.add("Username is required");
        }

        if (email == null || email.trim().isEmpty()) {
            errors.add("Email is required");
        } else if (!isValidEmail(email)) {
            errors.add("Invalid email format");
        }

        if (password == null || password.trim().isEmpty()) {
            errors.add("Password is required");
        } else if (password.length() < 8) {
            errors.add("Password must be at least 8 characters");
        }

        if (!errors.isEmpty()) {
            throw new IllegalArgumentException("User validation failed: " + 
                String.join(", ", errors));
        }
    }

    private boolean isValidEmail(String email) {
        return email.matches("^[A-Za-z0-9+_.-]+@(.+)$");
    }

    private String generateDefaultPassword() {
        return "DefaultPass123!";
    }

    // Pre-configured builders
    public static UserBuilder adminUser() {
        return new UserBuilder()
            .withRole(UserRole.ADMIN)
            .withAttribute("isAdmin", true);
    }

    public static UserBuilder premiumUser() {
        return new UserBuilder()
            .withRole(UserRole.PREMIUM)
            .withAttribute("subscriptionType", "PREMIUM")
            .withAttribute("trialEnded", true);
    }

    public static UserBuilder guestUser() {
        return new UserBuilder()
            .withRole(UserRole.GUEST)
            .withAttribute("isGuest", true);
    }
}

