public class EcommerceTestDataFactory implements TestDataFactory {

    private final Faker faker;

    public EcommerceTestDataFactory() {
        this.faker = new Faker();
    }

    @Override
    public UserTestData createUser(UserType userType) {
        UserBuilder builder = new UserBuilder()
            .withUsername(faker.name().username())
            .withEmail(faker.internet().emailAddress())
            .withName(faker.name().firstName(), faker.name().lastName())
            .withPhone(faker.phoneNumber().cellPhone())
            .withPassword(generateSecurePassword());

        switch (userType) {
            case ADMIN:
                builder.withRole(UserRole.ADMIN)
                       .withAttribute("permissions", Arrays.asList("READ", "WRITE", "DELETE"));
                break;
            case CUSTOMER:
                builder.withRole(UserRole.CUSTOMER)
                       .withAddress(createRandomAddress());
                break;
            case GUEST:
                builder.withRole(UserRole.GUEST)
                       .withAttribute("sessionOnly", true);
                break;
        }

        return builder.build();
    }

    @Override
    public ProductTestData createProduct(ProductCategory category) {
        ProductBuilder builder = new ProductBuilder()
            .withName(faker.commerce().productName())
            .withDescription(faker.lorem().paragraph())
            .withPrice(new BigDecimal(faker.commerce().price()))
            .withSku(faker.code().isbn10())
            .withCategory(category)
            .withStockQuantity(faker.number().numberBetween(0, 1000));

        // Add category-specific attributes
        switch (category) {
            case ELECTRONICS:
                builder.withAttribute("warranty", "2 years")
                       .withAttribute("brand", faker.company().name());
                break;
            case CLOTHING:
                builder.withAttribute("size", faker.options().option("S", "M", "L", "XL"))
                       .withAttribute("color", faker.color().name());
                break;
            case BOOKS:
                builder.withAttribute("author", faker.book().author())
                       .withAttribute("isbn", faker.code().isbn13());
                break;
        }

        return builder.build();
    }

    private String generateSecurePassword() {
        String upper = faker.regexify("[A-Z]{2}");
        String lower = faker.regexify("[a-z]{4}");
        String digits = faker.regexify("[0-9]{2}");
        String special = faker.regexify("[!@#$%^&*]{2}");

        String password = upper + lower + digits + special;
        List<Character> chars = password.chars()
            .mapToObj(c -> (char) c)
            .collect(Collectors.toList());
        Collections.shuffle(chars);

        return chars.stream()
            .map(String::valueOf)
            .collect(Collectors.joining());
    }

    private Address createRandomAddress() {
        return new AddressBuilder()
            .withStreet(faker.address().streetAddress())
            .withCity(faker.address().city())
            .withState(faker.address().state())
            .withZipCode(faker.address().zipCode())
            .withCountry(faker.address().country())
            .build();
    }
}

// Simple Dependency Injection Container
public class DIContainer {

    private final Map<Class<?>, Object> singletons;
    private final Map<Class<?>, Class<?>> implementations;
    private final Map<Class<?>, Supplier<?>> providers;

    public DIContainer() {
        this.singletons = new ConcurrentHashMap<>();
        this.implementations = new ConcurrentHashMap<>();
        this.providers = new ConcurrentHashMap<>();
    }

    public <T> void registerSingleton(Class<T> interfaceType, T instance) {
        singletons.put(interfaceType, instance);
    }

    public <T, U extends T> void registerImplementation(Class<T> interfaceType, 
                                                        Class<U> implementationType) {
        implementations.put(interfaceType, implementationType);
    }

    public <T> void registerProvider(Class<T> interfaceType, 
                                    Supplier<T> provider) {
        providers.put(interfaceType, provider);
    }

    @SuppressWarnings("unchecked")
    public <T> T getInstance(Class<T> interfaceType) {
        // Check singleton
        Object singleton = singletons.get(interfaceType);
        if (singleton != null) {
            return (T) singleton;
        }

        // Check provider
        Supplier<?> provider = providers.get(interfaceType);
        if (provider != null) {
            return (T) provider.get();
        }

        // Check implementation
        Class<?> implementation = implementations.get(interfaceType);
        if (implementation != null) {
            return createInstance(implementation);
        }

        // Try to create directly if it's a concrete class
        if (!interfaceType.isInterface() && !Modifier.isAbstract(interfaceType.getModifiers())) {
            return createInstance(interfaceType);
        }

        throw new IllegalStateException("No implementation registered for: " + interfaceType);
    }

    private <T> T createInstance(Class<T> clazz) {
        try {
            Constructor<T> constructor = getInjectableConstructor(clazz);

            if (constructor.getParameterCount() == 0) {
                return constructor.newInstance();
            }

            // Inject dependencies
            Class<?>[] paramTypes = constructor.getParameterTypes();
            Object[] params = new Object[paramTypes.length];

            for (int i = 0; i < paramTypes.length; i++) {
                params[i] = getInstance(paramTypes[i]);
            }

            return constructor.newInstance(params);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create instance of: " + clazz, e);
        }
    }

    private <T> Constructor<T> getInjectableConstructor(Class<T> clazz) {
        Constructor<?>[] constructors = clazz.getConstructors();

        if (constructors.length == 0) {
            throw new RuntimeException("No public constructors found for: " + clazz);
        }

        // Prefer constructor with parameters (for injection)
        Constructor<?> selected = constructors[0];
        for (Constructor<?> constructor : constructors) {
            if (constructor.getParameterCount() > selected.getParameterCount()) {
                selected = constructor;
            }
        }

        @SuppressWarnings("unchecked")
        Constructor<T> typedConstructor = (Constructor<T>) selected;
        return typedConstructor;
    }

    public void initialize() {
        // Initialize all singletons
        for (Class<?> type : singletons.keySet()) {
            getInstance(type); // Trigger initialization
        }
    }
}

// Object Pool for WebDriver Instances
public class WebDriverPool {

    private final BlockingQueue<PooledWebDriver> availableDrivers;
    private final Set<PooledWebDriver> inUseDrivers;
    private final BrowserConfig browserConfig;
    private final int maxSize;
    private final int minSize;
    private final AtomicInteger createdCount;

    public WebDriverPool(BrowserConfig browserConfig, int minSize, int maxSize) {
        this.browserConfig = browserConfig;
        this.minSize = minSize;
        this.maxSize = maxSize;
        this.availableDrivers = new LinkedBlockingQueue<>(maxSize);
        this.inUseDrivers = ConcurrentHashMap.newKeySet();
        this.createdCount = new AtomicInteger(0);

        initializePool();
    }

    private void initializePool() {
        for (int i = 0; i < minSize; i++) {
            availableDrivers.offer(createDriver());
        }
    }

    public PooledWebDriver borrowDriver() {
        try {
            PooledWebDriver driver = availableDrivers.poll(30, TimeUnit.SECONDS);

            if (driver == null) {
                // No available drivers, create new one if under max size
                if (createdCount.get() < maxSize) {
                    driver = createDriver();
                } else {
                    throw new TimeoutException("No drivers available in pool");
                }
            }

            // Validate driver health
            if (!isDriverHealthy(driver)) {
                invalidateDriver(driver);
                driver = createDriver();
            }

            inUseDrivers.add(driver);
            driver.setBorrowedTime(System.currentTimeMillis());

            return driver;
        } catch (Exception e) {
            throw new RuntimeException("Failed to borrow driver from pool", e);
        }
    }

    public void returnDriver(PooledWebDriver driver) {
        if (!inUseDrivers.contains(driver)) {
            throw new IllegalArgumentException("Driver not from this pool");
        }

        inUseDrivers.remove(driver);

        // Clean up driver state
        driver.cleanup();

        // Reset driver
        driver.getDriver().manage().deleteAllCookies();

        if (availableDrivers.size() < maxSize && isDriverHealthy(driver)) {
            availableDrivers.offer(driver);
        } else {
            // Destroy driver if pool is full or driver is unhealthy
            destroyDriver(driver);
        }
    }

    private PooledWebDriver createDriver() {
        WebDriver driver = DriverFactory.getInstance().createDriver();
        PooledWebDriver pooledDriver = new PooledWebDriver(driver, this);
        createdCount.incrementAndGet();
        return pooledDriver;
    }

    private boolean isDriverHealthy(PooledWebDriver driver) {
        try {
            // Check if driver is still responsive
            driver.getDriver().getCurrentUrl(); // Simple operation to check health
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private void invalidateDriver(PooledWebDriver driver) {
        destroyDriver(driver);
        createdCount.decrementAndGet();
    }

    private void destroyDriver(PooledWebDriver driver) {
        try {
            driver.getDriver().quit();
        } catch (Exception e) {
            // Log but continue
            System.err.println("Error destroying driver: " + e.getMessage());
        }
    }

    public void shutdown() {
        // Destroy all drivers
        availableDrivers.forEach(this::destroyDriver);
        availableDrivers.clear();

        inUseDrivers.forEach(this::destroyDriver);
        inUseDrivers.clear();
    }
}

public class PooledWebDriver {

    private final WebDriver driver;
    private final WebDriverPool pool;
    private long borrowedTime;

    public PooledWebDriver(WebDriver driver, WebDriverPool pool) {
        this.driver = driver;
        this.pool = pool;
    }

    public WebDriver getDriver() {
        return driver;
    }

    public void returnToPool() {
        pool.returnDriver(this);
    }

    public void cleanup() {
        // Close all windows except main
        Set<String> windowHandles = driver.getWindowHandles();
        String mainWindow = driver.getWindowHandle();

        for (String handle : windowHandles) {
            if (!handle.equals(mainWindow)) {
                driver.switchTo().window(handle);
                driver.close();
            }
        }

        driver.switchTo().window(mainWindow);
    }

    // Getters and setters
    public long getBorrowedTime() { return borrowedTime; }
    public void setBorrowedTime(long borrowedTime) { this.borrowedTime = borrowedTime; }
}

