    void scrollIntoView();
    boolean waitForVisible(int timeoutSeconds);
    boolean waitForClickable(int timeoutSeconds);
    String getFullXPath();
}

// Base Decorator
public abstract class WebElementDecorator implements EnhancedWebElement {
    protected final WebElement element;
    protected final WebDriver driver;

    public WebElementDecorator(WebElement element, WebDriver driver) {
        this.element = element;
        this.driver = driver;
    }

    @Override
    public void click() {
        element.click();
    }

    @Override
    public void submit() {
        element.submit();
    }

    @Override
    public void sendKeys(CharSequence... keysToSend) {
        element.sendKeys(keysToSend);
    }

    @Override
    public String getTagName() {
        return element.getTagName();
    }

    @Override
    public String getAttribute(String name) {
        return element.getAttribute(name);
    }

    @Override
    public boolean isSelected() {
        return element.isSelected();
    }

    @Override
    public boolean isEnabled() {
        return element.isEnabled();
    }

    @Override
    public String getText() {
        return element.getText();
    }

    @Override
    public List<WebElement> findElements(By by) {
        return element.findElements(by);
    }

    @Override
    public WebElement findElement(By by) {
        return element.findElement(by);
    }

    @Override
    public boolean isDisplayed() {
        return element.isDisplayed();
    }

    @Override
    public Point getLocation() {
        return element.getLocation();
    }

    @Override
    public Dimension getSize() {
        return element.getSize();
    }

    @Override
    public Rectangle getRect() {
        return element.getRect();
    }

    @Override
    public String getCssValue(String propertyName) {
        return element.getCssValue(propertyName);
    }

    @Override
    public <X> X getScreenshotAs(OutputType<X> target) throws WebDriverException {
        return element.getScreenshotAs(target);
    }

    @Override
    public void highlight() {
        JavascriptExecutor js = (JavascriptExecutor) driver;
        String originalStyle = element.getAttribute("style");

        js.executeScript(
            "arguments[0].setAttribute('style', arguments[1]);",
            element,
            "border: 3px solid red; background-color: yellow;"
        );

        try {
            Thread.sleep(500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        js.executeScript(
            "arguments[0].setAttribute('style', arguments[1]);",
            element,
            originalStyle != null ? originalStyle : ""
        );
    }

    @Override
    public void scrollIntoView() {
        JavascriptExecutor js = (JavascriptExecutor) driver;
        js.executeScript("arguments[0].scrollIntoView(true);", element);
    }

    @Override
    public boolean waitForVisible(int timeoutSeconds) {
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));
        try {
            wait.until(ExpectedConditions.visibilityOf(element));
            return true;
        } catch (TimeoutException e) {
            return false;
        }
    }

    @Override
    public boolean waitForClickable(int timeoutSeconds) {
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));
        try {
            wait.until(ExpectedConditions.elementToBeClickable(element));
            return true;
        } catch (TimeoutException e) {
            return false;
        }
    }

    @Override
    public String getFullXPath() {
        JavascriptExecutor js = (JavascriptExecutor) driver;
        return (String) js.executeScript(
            "function getPathTo(element) {\n" +
            "    if (element.id !== '') return '//' + element.tagName.toLowerCase() + '[@id=\"' + element.id + '\"]';\n" +
            "    if (element === document.body) return '/html/body';\n" +
            "    var ix = 0;\n" +
            "    var siblings = element.parentNode.childNodes;\n" +
            "    for (var i = 0; i < siblings.length; i++) {\n" +
            "        var sibling = siblings[i];\n" +
            "        if (sibling === element) return getPathTo(element.parentNode) + '/' + element.tagName.toLowerCase() + '[' + (ix + 1) + ']';\n" +
            "        if (sibling.nodeType === 1 && sibling.tagName === element.tagName) ix++;\n" +
            "    }\n" +
            "}\n" +
            "return getPathTo(arguments[0]);", element);
    }
}

// Logging Decorator
public class LoggingWebElementDecorator extends WebElementDecorator {
    private final Logger logger;

    public LoggingWebElementDecorator(WebElement element, WebDriver driver, Logger logger) {
        super(element, driver);
        this.logger = logger;
    }

    @Override
    public void click() {
        logger.info("Clicking element: " + getElementInfo());
        long startTime = System.currentTimeMillis();

        try {
            super.click();
            long duration = System.currentTimeMillis() - startTime;
            logger.info("Element clicked successfully in " + duration + "ms");
        } catch (Exception e) {
            logger.error("Failed to click element: " + getElementInfo(), e);
            throw e;
        }
    }

    @Override
    public void sendKeys(CharSequence... keysToSend) {
        String text = Arrays.stream(keysToSend)
            .map(CharSequence::toString)
            .collect(Collectors.joining());

        logger.info("Typing text '" + text + "' into element: " + getElementInfo());
        long startTime = System.currentTimeMillis();

        try {
            super.sendKeys(keysToSend);
            long duration = System.currentTimeMillis() - startTime;
            logger.info("Text typed successfully in " + duration + "ms");
        } catch (Exception e) {
            logger.error("Failed to type text into element: " + getElementInfo(), e);
            throw e;
        }
    }

    private String getElementInfo() {
        try {
            String tag = element.getTagName();
            String id = element.getAttribute("id");
            String name = element.getAttribute("name");
            String text = element.getText();

            StringBuilder info = new StringBuilder();
            info.append("<");
            info.append(tag);

            if (id != null && !id.isEmpty()) {
                info.append("#").append(id);
            }

            if (name != null && !name.isEmpty()) {
                info.append("[name='").append(name).append("']");
            }

            if (text != null && !text.isEmpty() && text.length() < 50) {
                info.append(" (text: '").append(text).append("')");
            }

            return info.toString();
        } catch (Exception e) {
            return "[Element info unavailable]";
        }
    }
}

// Retry Decorator
public class RetryWebElementDecorator extends WebElementDecorator {
    private final int maxRetries;
    private final long retryDelayMillis;

    public RetryWebElementDecorator(WebElement element, WebDriver driver, 
                                   int maxRetries, long retryDelayMillis) {
        super(element, driver);
        this.maxRetries = maxRetries;
        this.retryDelayMillis = retryDelayMillis;
    }

    @Override
    public void click() {
        retryOperation(() -> super.click(), "click");
    }

    @Override
    public void sendKeys(CharSequence... keysToSend) {
        retryOperation(() -> super.sendKeys(keysToSend), "sendKeys");
    }

    @Override
    public String getText() {
        return retryOperation(() -> super.getText(), "getText");
    }

    private <T> T retryOperation(Supplier<T> operation, String operationName) {
        int attempt = 0;
        Exception lastException = null;

        while (attempt < maxRetries) {
            try {
                return operation.get();
            } catch (StaleElementReferenceException e) {
                lastException = e;
                attempt++;

                if (attempt < maxRetries) {
                    try {
                        Thread.sleep(retryDelayMillis);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException("Retry interrupted", ie);
                    }

                    System.err.println("Stale element on " + operationName + ", retry " + attempt);
                }
            } catch (Exception e) {
                throw e;
            }
        }

        throw new RuntimeException("Failed after " + maxRetries + " retries: " + operationName, 
                                  lastException);
    }

    private void retryOperation(Runnable operation, String operationName) {
        retryOperation(() -> {
            operation.run();
            return null;
        }, operationName);
    }
}

