    private TestResult(String testName, boolean passed, String message, Throwable error) {
        this.testName = testName;
        this.passed = passed;
        this.message = message;
        this.error = error;
    }

    public static TestResult success(String testName, String message) {
        return new TestResult(testName, true, message, null);
    }

    public static TestResult failure(String testName, Throwable error) {
        return new TestResult(testName, false, error.getMessage(), error);
    }

    public static TestResult failure(String testName, String message) {
        return new TestResult(testName, false, message, null);
    }

    public boolean isPassed() { return passed; }
    public String getTestName() { return testName; }
