}

// Bridge Pattern for Test Reporting
public interface TestReporter {

    void testStarted(String testName);
    void testFinished(String testName, TestResult result);
    void stepExecuted(String stepName, StepResult result);
    void verificationPerformed(String verification, boolean passed);
    void screenshotCaptured(String screenshotName, byte[] screenshot);
    void generateReport();
}

// Abstraction
public abstract class TestReporterBridge {

    protected TestReporter implementor;

    public TestReporterBridge(TestReporter implementor) {
        this.implementor = implementor;
    }

    public void setImplementor(TestReporter implementor) {
        this.implementor = implementor;
    }

    public abstract void testStarted(String testName);
    public abstract void testFinished(String testName, TestResult result);
    public abstract void stepExecuted(String stepName, StepResult result);
    public abstract void verificationPerformed(String verification, boolean passed);
    public abstract void screenshotCaptured(String screenshotName, byte[] screenshot);
    public abstract void generateReport();
}

// Refined Abstraction
public class EnhancedTestReporter extends TestReporterBridge {

    private final Map<String, TestExecution> testExecutions;

    public EnhancedTestReporter(TestReporter implementor) {
        super(implementor);
        this.testExecutions = new HashMap<>();
    }

    @Override
    public void testStarted(String testName) {
        TestExecution execution = new TestExecution(testName);
        testExecutions.put(testName, execution);
        execution.setStartTime(System.currentTimeMillis());

        implementor.testStarted(testName);
    }

    @Override
    public void testFinished(String testName, TestResult result) {
        TestExecution execution = testExecutions.get(testName);
        if (execution != null) {
            execution.setEndTime(System.currentTimeMillis());
            execution.setResult(result);
            execution.calculateDuration();
        }

        implementor.testFinished(testName, result);
    }

    @Override
    public void stepExecuted(String stepName, StepResult result) {
        // Add analytics or processing
        if (result.isFailed()) {
            logStepFailure(stepName, result);
        }

        implementor.stepExecuted(stepName, result);
    }

    @Override
    public void verificationPerformed(String verification, boolean passed) {
        // Track verification statistics
        trackVerificationStats(verification, passed);

        implementor.verificationPerformed(verification, passed);
    }

    @Override
    public void screenshotCaptured(String screenshotName, byte[] screenshot) {
        // Compress or process screenshot
        byte[] processedScreenshot = processScreenshot(screenshot);

        implementor.screenshotCaptured(screenshotName, processedScreenshot);
    }

    @Override
    public void generateReport() {
        // Add summary information
        addReportSummary();

        implementor.generateReport();
    }

    private void logStepFailure(String stepName, StepResult result) {
        // Log failure details
        System.err.println("Step failed: " + stepName + " - " + result.getErrorMessage());
    }

    private void trackVerificationStats(String verification, boolean passed) {
        // Track for analytics
        // Could store in database or metrics system
    }

    private byte[] processScreenshot(byte[] screenshot) {
        // Implement screenshot processing if needed
        return screenshot;
    }

    private void addReportSummary() {
        // Calculate summary statistics
        long totalTests = testExecutions.size();
        long passedTests = testExecutions.values().stream()
            .filter(e -> e.getResult() != null && e.getResult().isPassed())
            .count();
        long failedTests = totalTests - passedTests;

        double passRate = totalTests > 0 ? (passedTests * 100.0 / totalTests) : 0.0;

        System.out.println("Report Summary:");
        System.out.println("Total Tests: " + totalTests);
        System.out.println("Passed: " + passedTests);
        System.out.println("Failed: " + failedTests);
        System.out.println("Pass Rate: " + String.format("%.2f", passRate) + "%");
    }
}

// Concrete Implementor: HTML Reporter
public class HtmlTestReporter implements TestReporter {

    private final String reportDir;
    private final List<TestReport> reports;

    public HtmlTestReporter(String reportDir) {
        this.reportDir = reportDir;
        this.reports = new ArrayList<>();
        ensureReportDirectory();
    }

    private void ensureReportDirectory() {
        File dir = new File(reportDir);
        if (!dir.exists()) {
            dir.mkdirs();
        }
    }

    @Override
    public void testStarted(String testName) {
        TestReport report = new TestReport(testName);
        reports.add(report);

        System.out.println("Test started: " + testName);
    }

    @Override
    public void testFinished(String testName, TestResult result) {
        TestReport report = findReport(testName);
        if (report != null) {
            report.setResult(result);
            report.setEndTime(System.currentTimeMillis());
        }

        System.out.println("Test finished: " + testName + " - " + 
                          (result.isPassed() ? "PASSED" : "FAILED"));
    }

    @Override
    public void stepExecuted(String stepName, StepResult result) {
        TestReport report = getCurrentReport();
        if (report != null) {
            report.addStep(stepName, result);
        }
    }

    @Override
    public void verificationPerformed(String verification, boolean passed) {
        TestReport report = getCurrentReport();
        if (report != null) {
            report.addVerification(verification, passed);
        }
    }

    @Override
    public void screenshotCaptured(String screenshotName, byte[] screenshot) {
        TestReport report = getCurrentReport();
        if (report != null) {
            // Save screenshot to file
            String screenshotPath = saveScreenshot(screenshotName, screenshot);
            report.addScreenshot(screenshotName, screenshotPath);
        }
    }

    @Override
    public void generateReport() {
        // Generate HTML report
        String html = generateHtmlReport();

        // Write to file
        String reportPath = reportDir + "/test-report.html";
        try (FileWriter writer = new FileWriter(reportPath)) {
            writer.write(html);
        } catch (IOException e) {
            throw new RuntimeException("Failed to write HTML report", e);
        }

        System.out.println("HTML report generated: " + reportPath);
    }

    private String saveScreenshot(String name, byte[] screenshot) {
        String filename = name + "_" + System.currentTimeMillis() + ".png";
        String filepath = reportDir + "/" + filename;

        try (FileOutputStream fos = new FileOutputStream(filepath)) {
            fos.write(screenshot);
        } catch (IOException e) {
            System.err.println("Failed to save screenshot: " + e.getMessage());
            return null;
        }

        return filename;
    }

    private String generateHtmlReport() {
        StringBuilder html = new StringBuilder();

        html.append("<!DOCTYPE html>\n");
        html.append("<html>\n");
        html.append("<head>\n");
        html.append("    <title>Test Automation Report</title>\n");
        html.append("    <style>\n");
        html.append("        body { font-family: Arial, sans-serif; margin: 20px; }\n");
        html.append("        .test { border: 1px solid #ddd; margin: 10px 0; padding: 10px; }\n");
        html.append("        .passed { background-color: #d4edda; }\n");
        html.append("        .failed { background-color: #f8d7da; }\n");
        html.append("        .step { margin-left: 20px; }\n");
        html.append("        .verification { margin-left: 40px; font-style: italic; }\n");
        html.append("        .screenshot { margin-left: 40px; }\n");
        html.append("        img { max-width: 300px; border: 1px solid #ccc; }\n");
        html.append("    </style>\n");
        html.append("</head>\n");
        html.append("<body>\n");
        html.append("    <h1>Test Automation Report</h1>\n");
        html.append("    <p>Generated: " + new Date() + "</p>\n");

        // Summary
        long total = reports.size();
        long passed = reports.stream().filter(r -> r.getResult() != null && r.getResult().isPassed()).count();
        long failed = total - passed;

        html.append("    <h2>Summary</h2>\n");
        html.append("    <p>Total Tests: " + total + "</p>\n");
        html.append("    <p>Passed: " + passed + "</p>\n");
        html.append("    <p>Failed: " + failed + "</p>\n");

        // Test details
        html.append("    <h2>Test Details</h2>\n");
        for (TestReport report : reports) {
            String statusClass = report.getResult() != null && report.getResult().isPassed() ? "passed" : "failed";

            html.append("    <div class='test " + statusClass + "'>\n");
            html.append("        <h3>" + report.getTestName() + "</h3>\n");

            if (report.getResult() != null) {
                html.append("        <p>Status: " + (report.getResult().isPassed() ? "PASSED" : "FAILED") + "</p>\n");
                html.append("        <p>Duration: " + report.getDuration() + "ms</p>\n");

                if (!report.getResult().isPassed() && report.getResult().getErrorMessage() != null) {
                    html.append("        <p>Error: " + report.getResult().getErrorMessage() + "</p>\n");
                }
            }

            // Steps
            if (!report.getSteps().isEmpty()) {
                html.append("        <h4>Steps:</h4>\n");
                for (Map.Entry<String, StepResult> step : report.getSteps().entrySet()) {
                    html.append("        <div class='step'>" + step.getKey() + 
                              " - " + (step.getValue().isPassed() ? "✓" : "✗") + "</div>\n");
                }
            }

            // Screenshots
            if (!report.getScreenshots().isEmpty()) {
                html.append("        <h4>Screenshots:</h4>\n");
                for (Map.Entry<String, String> screenshot : report.getScreenshots().entrySet()) {
                    html.append("        <div class='screenshot'>\n");
                    html.append("            <p>" + screenshot.getKey() + "</p>\n");
                    html.append("            <img src='" + screenshot.getValue() + "' alt='" + screenshot.getKey() + "'>\n");
                    html.append("        </div>\n");
                }
            }

            html.append("    </div>\n");
        }

        html.append("</body>\n");
        html.append("</html>");

        return html.toString();
    }

    private TestReport findReport(String testName) {
        return reports.stream()
            .filter(r -> r.getTestName().equals(testName))
            .findFirst()
            .orElse(null);
    }

    private TestReport getCurrentReport() {
        if (!reports.isEmpty()) {
            return reports.get(reports.size() - 1);
        }
        return null;
    }
}

// Proxy Pattern for Lazy Page Objects
public interface PageObject {

    void initialize();
    boolean isInitialized();
    void performAction(String action);
    Object getElement(String elementName);
}

// Real Page Object
public class RealLoginPage implements PageObject {

    private final WebDriver driver;
    private WebElement usernameField;
    private WebElement passwordField;
    private WebElement loginButton;
    private boolean initialized = false;

    public RealLoginPage(WebDriver driver) {
        this.driver = driver;
    }

    @Override
    public void initialize() {
        System.out.println("Initializing RealLoginPage...");

        // This is expensive operation
        usernameField = driver.findElement(By.id("username"));
        passwordField = driver.findElement(By.id("password"));
        loginButton = driver.findElement(By.id("login-button"));

        initialized = true;
        System.out.println("RealLoginPage initialized");
    }

    @Override
    public boolean isInitialized() {
        return initialized;
    }

    @Override
    public void performAction(String action) {
        if (!initialized) {
            throw new IllegalStateException("Page not initialized");
        }

        switch (action) {
            case "login":
                usernameField.sendKeys("testuser");
                passwordField.sendKeys("password");
                loginButton.click();
                break;
            case "clear":
                usernameField.clear();
                passwordField.clear();
                break;
            default:
                throw new IllegalArgumentException("Unknown action: " + action);
        }
    }

    @Override
    public Object getElement(String elementName) {
        if (!initialized) {
            throw new IllegalStateException("Page not initialized");
        }

        switch (elementName) {
            case "username": return usernameField;
            case "password": return passwordField;
            case "loginButton": return loginButton;
            default: throw new IllegalArgumentException("Unknown element: " + elementName);
        }
    }
}

// Proxy Page Object
public class LazyLoginPageProxy implements PageObject {

    private final WebDriver driver;
    private RealLoginPage realPage;
    private boolean initializationAttempted = false;

    public LazyLoginPageProxy(WebDriver driver) {
        this.driver = driver;
    }

    @Override
    public void initialize() {
        // Lazy initialization - only create real object when needed
        if (realPage == null) {
            realPage = new RealLoginPage(driver);
        }
        realPage.initialize();
    }

    @Override
    public boolean isInitialized() {
        return realPage != null && realPage.isInitialized();
    }

    @Override
    public void performAction(String action) {
        ensureInitialized();

        // Add logging
        System.out.println("Performing action: " + action);
        long startTime = System.currentTimeMillis();

        try {
            realPage.performAction(action);
            long duration = System.currentTimeMillis() - startTime;
            System.out.println("Action completed in " + duration + "ms");
        } catch (Exception e) {
            System.err.println("Action failed: " + e.getMessage());
            throw e;
        }
    }

    @Override
    public Object getElement(String elementName) {
        ensureInitialized();

        // Add access control
        if (elementName.contains("password")) {
            System.out.println("Warning: Accessing password element");
        }

        return realPage.getElement(elementName);
    }

    private void ensureInitialized() {
        if (realPage == null) {
            realPage = new RealLoginPage(driver);
        }

        if (!realPage.isInitialized()) {
            realPage.initialize();
        }
    }

    // Additional proxy functionality
    public void reset() {
        if (realPage != null) {
            realPage = null;
            initializationAttempted = false;
            System.out.println("Proxy reset");
        }
    }
}

// Caching Proxy for Element Lookups
public class CachingElementProxy implements InvocationHandler {

    private final WebDriver driver;
    private final Map<By, WebElement> elementCache;
    private final Map<By, List<WebElement>> elementsCache;

    public CachingElementProxy(WebDriver driver) {
        this.driver = driver;
        this.elementCache = new ConcurrentHashMap<>();
        this.elementsCache = new ConcurrentHashMap<>();
    }

    public static WebDriver createCachingProxy(WebDriver driver) {
        return (WebDriver) Proxy.newProxyInstance(
            WebDriver.class.getClassLoader(),
            new Class[] { WebDriver.class },
            new CachingElementProxy(driver)
        );
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        // Handle findElement with caching
        if (method.getName().equals("findElement") && args.length == 1 && args[0] instanceof By) {
            By locator = (By) args[0];

            // Check cache first
            WebElement cached = elementCache.get(locator);
            if (cached != null) {
                try {
                    // Verify element is still valid
                    cached.isEnabled();
                    System.out.println("Returning cached element for: " + locator);
                    return cached;
                } catch (StaleElementReferenceException e) {
                    // Element is stale, remove from cache and fetch fresh
                    System.out.println("Cached element stale for: " + locator);
                    elementCache.remove(locator);
                }
            }

            // Not in cache or stale, fetch fresh
            WebElement freshElement = (WebElement) method.invoke(driver, args);
            elementCache.put(locator, freshElement);
            System.out.println("Cached fresh element for: " + locator);
            return freshElement;
        }

        // Handle findElements with caching
        if (method.getName().equals("findElements") && args.length == 1 && args[0] instanceof By) {
            By locator = (By) args[0];

            // Check cache first
            List<WebElement> cached = elementsCache.get(locator);
            if (cached != null && !cached.isEmpty()) {
                try {
                    // Verify first element is still valid
                    cached.get(0).isEnabled();
                    System.out.println("Returning cached elements for: " + locator);
                    return cached;
                } catch (StaleElementReferenceException e) {
                    // Elements are stale, remove from cache and fetch fresh
                    System.out.println("Cached elements stale for: " + locator);
                    elementsCache.remove(locator);
                }
            }

            // Not in cache or stale, fetch fresh
            @SuppressWarnings("unchecked")
            List<WebElement> freshElements = (List<WebElement>) method.invoke(driver, args);
            elementsCache.put(locator, freshElements);
            System.out.println("Cached fresh elements for: " + locator);
            return freshElements;
        }

        // Clear cache on navigation
        if (method.getName().equals("get") || method.getName().equals("navigate")) {
            System.out.println("Clearing element cache due to navigation");
            clearCache();
        }

        // For all other methods, delegate to real driver
        return method.invoke(driver, args);
    }

    private void clearCache() {
        elementCache.clear();
        elementsCache.clear();
        System.out.println("Element cache cleared");
    }

    public void invalidateCache(By locator) {
        elementCache.remove(locator);
        elementsCache.remove(locator);
        System.out.println("Cache invalidated for: " + locator);
    }
}

