        this.codeFormatter = new CodeFormatter();
        this.testRunner = new TestRunner();
    }

    public RefactoringResult applyRefactoring(
            String filePath, 
            RefactoringSuggestion suggestion) {

        RefactoringResult result = new RefactoringResult(suggestion);

        try {
            // Backup original file
            String backup = FileUtils.readFileToString(new File(filePath), "UTF-8");

            // Apply refactoring
            String refactoredCode = applyRefactoringToFile(filePath, suggestion);

            // Format code
            String formattedCode = codeFormatter.format(refactoredCode);

            // Write back
            FileUtils.writeStringToFile(new File(filePath), formattedCode, "UTF-8");

            // Run affected tests
            TestRunResult testResult = testRunner.runTestsForFile(filePath);

            if (testResult.allPassed()) {
                result.setSuccess(true);
                result.setMessage("Refactoring applied successfully");
            } else {
                // Rollback on test failure
                FileUtils.writeStringToFile(new File(filePath), backup, "UTF-8");
                result.setSuccess(false);
                result.setMessage("Refactoring failed: tests broke. Rolled back changes.");
                result.setTestFailures(testResult.getFailures());
            }

        } catch (Exception e) {
            result.setSuccess(false);
            result.setMessage("Refactoring failed: " + e.getMessage());
        }

        return result;
    }

    private String applyRefactoringToFile(
            String filePath, 
            RefactoringSuggestion suggestion) throws Exception {

        String content = FileUtils.readFileToString(new File(filePath), "UTF-8");

        switch (suggestion.getType()) {
            case "Extract Method":
                return refactoringEngine.extractMethod(content, suggestion);
            case "Extract Constant":
                return refactoringEngine.extractConstant(content, suggestion);
            case "Rename Variable":
                return refactoringEngine.renameVariable(content, suggestion);
            case "Inline Method":
                return refactoringEngine.inlineMethod(content, suggestion);
            default:
                throw new IllegalArgumentException("Unsupported refactoring type: " + 
                    suggestion.getType());
        }
    }
}

// Quality Gate for Pull Requests
public class PullRequestQualityGate {

    private final CodeQualityChecker qualityChecker;
    private final TestQualityAnalyzer testAnalyzer;
    private final Map<String, Double> qualityThresholds;

    public PullRequestQualityGate() {
        this.qualityChecker = new CodeQualityChecker();
        this.testAnalyzer = new TestQualityAnalyzer();
        this.qualityThresholds = loadQualityThresholds();
    }

    public QualityGateResult evaluatePullRequest(
            String sourceBranch, 
            String targetBranch) {

        QualityGateResult result = new QualityGateResult();

        // Get changed files
        List<String> changedFiles = getChangedFiles(sourceBranch, targetBranch);

        // Check each changed file
        for (String filePath : changedFiles) {
            if (filePath.endsWith(".java")) {
                QualityReport report = qualityChecker.checkCodeQuality(filePath);

                // Check against thresholds
                if (!meetsQualityThresholds(report)) {
                    result.addFailure(filePath, 
                        "Code quality below threshold: " + report.getOverallScore());
                }

                // Check test-specific quality for test files
                if (filePath.contains("Test") || filePath.contains("test")) {
                    TestQualityReport testReport = testAnalyzer.analyzeTestFile(filePath);
                    if (!testReport.isAcceptable()) {
                        result.addFailure(filePath, 
                            "Test quality issues: " + testReport.getIssues());
                    }
                }
            }
        }

        // Overall evaluation
        if (result.hasFailures()) {
            result.setPassed(false);
            result.setMessage("Quality gate failed: " + result.getFailureCount() + " issues");
        } else {
            result.setPassed(true);
            result.setMessage("Quality gate passed");
        }

        return result;
    }

    private boolean meetsQualityThresholds(QualityReport report) {
        return report.getOverallScore() >= qualityThresholds.get("overall_score") &&
               report.getMetricValue("complexity") <= qualityThresholds.get("max_complexity") &&
               report.getMetricValue("duplication") <= qualityThresholds.get("max_duplication") &&
               report.getViolationCount() <= qualityThresholds.get("max_violations");
    }
}

// Technical Debt Tracking System
public class TechnicalDebtManager {

    private final DebtInventory inventory;
    private final DebtAnalyzer analyzer;
    private final DebtPrioritizer prioritizer;
    private final PaymentPlanner paymentPlanner;

    public TechnicalDebtManager(String projectPath) {
        this.inventory = new DebtInventory(projectPath);
        this.analyzer = new DebtAnalyzer();
        this.prioritizer = new DebtPrioritizer();
        this.paymentPlanner = new PaymentPlanner();
    }

    public DebtReport analyzeTechnicalDebt() {
        // Discover debt items
        List<DebtItem> debtItems = inventory.discoverDebt();

        // Analyze each item
        for (DebtItem item : debtItems) {
            analyzer.analyzeDebtItem(item);
        }

        // Create report
        DebtReport report = new DebtReport();
        report.setDebtItems(debtItems);
        report.setTotalDebt(calculateTotalDebt(debtItems));
        report.setTotalInterest(calculateTotalInterest(debtItems));
        report.setDebtRatio(calculateDebtRatio(debtItems));

        return report;
    }

    public PaymentPlan createPaymentPlan(DebtReport report, int availableCapacity) {
        // Prioritize debt items
        List<DebtItem> prioritized = prioritizer.prioritize(report.getDebtItems());

        // Create payment plan
        PaymentPlan plan = paymentPlanner.createPlan(prioritized, availableCapacity);

        return plan;
    }

    public void trackPaymentProgress(PaymentPlan plan) {
        PaymentTracker tracker = new PaymentTracker(plan);
        tracker.trackProgress();

        // Generate progress report
        ProgressReport progressReport = tracker.generateProgressReport();

        // Update stakeholders
        notifyStakeholders(progressReport);
    }

    private double calculateTotalDebt(List<DebtItem> debtItems) {
        return debtItems.stream()
            .mapToDouble(DebtItem::getPrincipal)
            .sum();
    }

    private double calculateTotalInterest(List<DebtItem> debtItems) {
        return debtItems.stream()
            .mapToDouble(DebtItem::getAnnualInterest)
            .sum();
    }

    private double calculateDebtRatio(List<DebtItem> debtItems) {
        double totalDebt = calculateTotalDebt(debtItems);
        double codeValue = estimateCodeValue();

        return codeValue > 0 ? (totalDebt / codeValue) * 100 : 0;
    }

    private double estimateCodeValue() {
        // Estimate based on development cost
        // In reality, this would be more sophisticated
        return 100000; // $100k estimated value
    }
}

// Debt Item Representation
public class DebtItem {
    private final String id;
    private final DebtType type;
    private final String description;
    private final String location;
    private final DebtSeverity severity;
    private final double principal; // cost to fix
    private final double annualInterest; // annual cost of not fixing
    private final LocalDate createdDate;
    private LocalDate dueDate;
    private DebtStatus status;
    private String assignedTo;

    public DebtItem(String id, DebtType type, String description, 
                   String location, DebtSeverity severity) {
        this.id = id;
        this.type = type;
        this.description = description;
        this.location = location;
        this.severity = severity;
        this.createdDate = LocalDate.now();
        this.status = DebtStatus.OPEN;

        // Estimate principal and interest based on type and severity
        this.principal = estimatePrincipal(type, severity);
        this.annualInterest = estimateAnnualInterest(type, severity);
    }

    private double estimatePrincipal(DebtType type, DebtSeverity severity) {
        double basePrincipal = 0;

        switch (type) {
            case FLAKY_TEST:
                basePrincipal = 8.0; // hours
                break;
            case DUPLICATED_CODE:
                basePrincipal = 4.0;
                break;
            case BRITTLE_TEST:
                basePrincipal = 6.0;
                break;
            case OUTDATED_DEPENDENCY:
                basePrincipal = 2.0;
                break;
            case POOR_PERFORMANCE:
                basePrincipal = 12.0;
                break;
            default:
                basePrincipal = 4.0;
        }

        // Adjust for severity
        switch (severity) {
            case CRITICAL: return basePrincipal * 2.0;
            case HIGH: return basePrincipal * 1.5;
            case MEDIUM: return basePrincipal;
            case LOW: return basePrincipal * 0.5;
            default: return basePrincipal;
        }
    }

    private double estimateAnnualInterest(DebtType type, DebtSeverity severity) {
        double baseInterest = 0;

        switch (type) {
            case FLAKY_TEST:
                baseInterest = 40.0; // hours per year
                break;
            case DUPLICATED_CODE:
                baseInterest = 20.0;
                break;
            case BRITTLE_TEST:
                baseInterest = 60.0;
                break;
            case OUTDATED_DEPENDENCY:
                baseInterest = 10.0;
                break;
            case POOR_PERFORMANCE:
                baseInterest = 30.0;
                break;
            default:
                baseInterest = 20.0;
        }

        // Adjust for severity
        switch (severity) {
            case CRITICAL: return baseInterest * 3.0;
            case HIGH: return baseInterest * 2.0;
            case MEDIUM: return baseInterest;
            case LOW: return baseInterest * 0.5;
            default: return baseInterest;
        }
    }

    public double getTotalCost(int years) {
        // Total cost = principal + (interest * years)
        return principal + (annualInterest * years);
    }

    public double getRoi(int years) {
        // ROI = (interest saved - principal) / principal
        double interestSaved = annualInterest * years;
        return (interestSaved - principal) / principal;
    }

    // Getters and setters
    public String getId() { return id; }
    public DebtType getType() { return type; }
    public String getDescription() { return description; }
    public double getPrincipal() { return principal; }
    public double getAnnualInterest() { return annualInterest; }
}

// Debt Inventory
public class DebtInventory {
    private final String projectPath;
    private final CodeAnalyzer codeAnalyzer;
    private final TestAnalyzer testAnalyzer;
    private final DependencyAnalyzer dependencyAnalyzer;

    public DebtInventory(String projectPath) {
        this.projectPath = projectPath;
        this.codeAnalyzer = new CodeAnalyzer(projectPath);
        this.testAnalyzer = new TestAnalyzer(projectPath);
        this.dependencyAnalyzer = new DependencyAnalyzer(projectPath);
    }

    public List<DebtItem> discoverDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Discover code quality debt
        debtItems.addAll(discoverCodeQualityDebt());

        // Discover test quality debt
        debtItems.addAll(discoverTestQualityDebt());

        // Discover dependency debt
        debtItems.addAll(discoverDependencyDebt());

        // Discover performance debt
        debtItems.addAll(discoverPerformanceDebt());

        return debtItems;
    }

    private List<DebtItem> discoverCodeQualityDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Analyze code smells
        List<CodeSmell> smells = codeAnalyzer.detectCodeSmells();

        for (CodeSmell smell : smells) {
            if (smell.getSeverity() >= CodeSmell.Severity.MAJOR) {
                DebtItem item = new DebtItem(
                    "CODE-" + UUID.randomUUID().toString().substring(0, 8),
                    DebtType.CODE_SMELL,
                    "Code smell: " + smell.getType(),
                    smell.getLocation(),
                    convertSeverity(smell.getSeverty())
                );
                debtItems.add(item);
            }
        }

        // Analyze duplication
        double duplicationRate = codeAnalyzer.calculateDuplication();
        if (duplicationRate > 5.0) { // More than 5% duplication
            DebtItem item = new DebtItem(
                "DUP-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.DUPLICATED_CODE,
                "High code duplication: " + String.format("%.1f", duplicationRate) + "%",
                projectPath,
                duplicationRate > 10.0 ? DebtSeverity.HIGH : DebtSeverity.MEDIUM
            );
            debtItems.add(item);
        }

        return debtItems;
    }

    private List<DebtItem> discoverTestQualityDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Analyze flaky tests
        List<FlakyTest> flakyTests = testAnalyzer.identifyFlakyTests();
        for (FlakyTest flakyTest : flakyTests) {
            DebtItem item = new DebtItem(
                "FLAKY-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.FLAKY_TEST,
                "Flaky test: " + flakyTest.getTestName(),
                flakyTest.getLocation(),
                flakyTest.getFlakinessRate() > 0.3 ? DebtSeverity.CRITICAL : DebtSeverity.HIGH
            );
            debtItems.add(item);
        }

        // Analyze brittle tests
        List<BrittleTest> brittleTests = testAnalyzer.identifyBrittleTests();
        for (BrittleTest brittleTest : brittleTests) {
            DebtItem item = new DebtItem(
                "BRITTLE-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.BRITTLE_TEST,
                "Brittle test: " + brittleTest.getTestName(),
                brittleTest.getLocation(),
                DebtSeverity.HIGH
            );
            debtItems.add(item);
        }

        return debtItems;
    }

    private List<DebtItem> discoverDependencyDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Analyze outdated dependencies
        List<OutdatedDependency> outdatedDeps = dependencyAnalyzer.findOutdatedDependencies();

        for (OutdatedDependency dep : outdatedDeps) {
            DebtSeverity severity;
            if (dep.isSecurityVulnerability()) {
                severity = DebtSeverity.CRITICAL;
            } else if (dep.getVersionsBehind() > 5) {
                severity = DebtSeverity.HIGH;
            } else if (dep.getVersionsBehind() > 2) {
                severity = DebtSeverity.MEDIUM;
            } else {
                severity = DebtSeverity.LOW;
            }

            DebtItem item = new DebtItem(
                "DEP-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.OUTDATED_DEPENDENCY,
                "Outdated dependency: " + dep.getName() + " (" + 
                dep.getCurrentVersion() + " -> " + dep.getLatestVersion() + ")",
                dep.getLocation(),
                severity
            );
            debtItems.add(item);
        }

        return debtItems;
    }

    private DebtSeverity convertSeverity(CodeSmell.Severity smellSeverity) {
        switch (smellSeverity) {
            case BLOCKER: return DebtSeverity.CRITICAL;
            case CRITICAL: return DebtSeverity.HIGH;
            case MAJOR: return DebtSeverity.MEDIUM;
            case MINOR: return DebtSeverity.LOW;
            default: return DebtSeverity.LOW;
        }
    }
}

// Debt Prioritizer
public class DebtPrioritizer {

    public List<DebtItem> prioritize(List<DebtItem> debtItems) {
        return debtItems.stream()
            .sorted((item1, item2) -> {
                // Priority = f(severity, interest, age, roi)
                double priority1 = calculatePriority(item1);
                double priority2 = calculatePriority(item2);

                return Double.compare(priority2, priority1); // Higher priority first
            })
            .collect(Collectors.toList());
    }

    private double calculatePriority(DebtItem item) {
        double priority = 0;

        // Severity weight (40%)
        priority += getSeverityWeight(item.getSeverity()) * 0.4;

        // Interest weight (30%)
        priority += normalizeInterest(item.getAnnualInterest()) * 0.3;

        // Age weight (20%)
        priority += calculateAgeWeight(item.getCreatedDate()) * 0.2;

        // ROI weight (10%)
        priority += calculateRoiWeight(item) * 0.1;

        return priority;
    }

    private double getSeverityWeight(DebtSeverity severity) {
        switch (severity) {
            case CRITICAL: return 1.0;
            case HIGH: return 0.75;
            case MEDIUM: return 0.5;
            case LOW: return 0.25;
            default: return 0.5;
        }
    }

    private double normalizeInterest(double interest) {
        // Normalize to 0-1 range
        // Assume max interest is 100 hours/year
        return Math.min(interest / 100.0, 1.0);
    }

    private double calculateAgeWeight(LocalDate createdDate) {
        long daysOld = ChronoUnit.DAYS.between(createdDate, LocalDate.now());

        // Older debt gets higher weight, up to 180 days
        return Math.min(daysOld / 180.0, 1.0);
    }

    private double calculateRoiWeight(DebtItem item) {
        double roi = item.getRoi(1); // 1-year ROI

        // Higher ROI gets higher weight
        return Math.min(roi / 5.0, 1.0); // Cap at 500% ROI
    }
}

// Debt Dashboard
public class DebtDashboard {
    private final TechnicalDebtManager debtManager;
    private final DashboardRenderer renderer;

    public DebtDashboard(TechnicalDebtManager debtManager) {
        this.debtManager = debtManager;
        this.renderer = new DashboardRenderer();
    }

    public String generateDashboard() {
        DebtReport report = debtManager.analyzeTechnicalDebt();

        // Create dashboard data
        DashboardData data = new DashboardData();
        data.setTotalDebt(report.getTotalDebt());
        data.setTotalInterest(report.getTotalInterest());
        data.setDebtRatio(report.getDebtRatio());
        data.setDebtByType(aggregateDebtByType(report));
        data.setDebtBySeverity(aggregateDebtBySeverity(report));
        data.setTopDebtItems(getTopDebtItems(report, 10));
        data.setTrendData(getTrendData());

        // Render dashboard
        return renderer.render(data);
    }

    public String generateExecutiveSummary() {
        DebtReport report = debtManager.analyzeTechnicalDebt();

        StringBuilder summary = new StringBuilder();
        summary.append("TECHNICAL DEBT EXECUTIVE SUMMARY\n");
        summary.append("================================\n\n");

        summary.append(String.format("Total Debt: %.1f hours\n", report.getTotalDebt()));
        summary.append(String.format("Annual Interest: %.1f hours/year\n", report.getTotalInterest()));
        summary.append(String.format("Debt Ratio: %.1f%%\n\n", report.getDebtRatio()));

        summary.append("Top Debt Items:\n");
        List<DebtItem> topItems = getTopDebtItems(report, 5);
        for (int i = 0; i < topItems.size(); i++) {
            DebtItem item = topItems.get(i);
            summary.append(String.format("%d. %s (Severity: %s, Cost: %.1f hours)\n", 
                i + 1, item.getDescription(), item.getSeverity(), item.getPrincipal()));
        }

        summary.append("\nRecommendations:\n");
        summary.append("1. Allocate 20% of capacity to debt reduction\n");
        summary.append("2. Focus on critical and high severity items first\n");
        summary.append("3. Establish debt prevention practices\n");

        return summary.toString();
    }
}

// Complete Jenkins Pipeline with Test Strategy
pipeline {
    agent any

    parameters {
        string(name: 'BRANCH', defaultValue: 'main', description: 'Branch to build')
        choice(name: 'DEPLOY_ENV', choices: ['staging', 'production'], description: 'Deployment environment')
        booleanParam(name: 'RUN_PERF_TESTS', defaultValue: false, description: 'Run performance tests')
        booleanParam(name: 'RUN_SECURITY_SCAN', defaultValue: true, description: 'Run security scans')
    }

    environment {
        // Project settings
        PROJECT_NAME = 'ecommerce-app'
        REPO_URL = 'https://github.com/company/ecommerce'
        DOCKER_REGISTRY = 'registry.company.com'

        // Quality gate thresholds
        UNIT_TEST_PASS_RATE = '95'
        UNIT_TEST_COVERAGE = '80'
        INTEGRATION_TEST_PASS_RATE = '90'
        UI_TEST_PASS_RATE = '85'

        // Performance thresholds
        P95_RESPONSE_TIME = '2000'
        MAX_ERROR_RATE = '1'

        // Security thresholds
        MAX_CRITICAL_VULNERABILITIES = '0'
        MAX_HIGH_VULNERABILITIES = '2'
    }

    stages {
        // Stage 1: Setup and checkout
        stage('Setup') {
            steps {
                script {
                    echo "Starting pipeline for ${PROJECT_NAME}"

                    // Checkout code
                    checkout([
                        $class: 'GitSCM',
                        branches: [[name: "*/${params.BRANCH}"]],
                        extensions: [[$class: 'CleanBeforeCheckout']],
                        userRemoteConfigs: [[url: "${REPO_URL}"]]
                    ])

                    // Setup environment
                    sh 'mvn --version'
                    sh 'java --version'

                    // Initialize build number
                    BUILD_NUMBER = env.BUILD_NUMBER
                    BUILD_TAG = "${PROJECT_NAME}-${BUILD_NUMBER}"
                }
            }
        }

        // Stage 2: Build and unit tests
        stage('Build & Unit Tests') {
            agent {
                docker {
                    image 'maven:3.8-openjdk-17'
                    args '-v $HOME/.m2:/root/.m2'
                }
            }
            steps {
                script {
                    // Compile and run unit tests
                    sh 'mvn clean compile test -DskipITs'

                    // Generate reports
                    sh 'mvn jacoco:report surefire-report:report'

                    // Check quality gates
                    def unitTestResults = junit 'target/surefire-reports/*.xml'
                    def coverage = readFile 'target/site/jacoco/jacoco.xml'

                    // Parse coverage
                    def coveragePercent = parseCoverage(coverage)

                    // Enforce quality gates
                    if (unitTestResults.failCount > 0) {
                        error "Unit tests failed: ${unitTestResults.failCount} failures"
                    }

                    if (coveragePercent < UNIT_TEST_COVERAGE.toInteger()) {
                        error "Code coverage ${coveragePercent}% below threshold ${UNIT_TEST_COVERAGE}%"
                    }

                    echo "Unit tests passed: ${unitTestResults.totalCount - unitTestResults.failCount}/${unitTestResults.totalCount}"
                    echo "Code coverage: ${coveragePercent}%"
                }
            }
            post {
                always {
                    // Archive test results
                    archiveArtifacts 'target/surefire-reports/*.xml'

                    // Publish HTML report
                    publishHTML([
                        allowMissing: false,
                        alwaysLinkToLastBuild: true,
                        keepAll: true,
                        reportDir: 'target/site',
                        reportFiles: 'surefire-report.html',
                        reportName: 'Unit Test Report'
                    ])
                }
            }
        }

        // Stage 3: Integration tests (parallel with security)
        stage('Integration & Security') {
            parallel {
                stage('Integration Tests') {
                    agent {
                        docker {
                            image 'maven:3.8-openjdk-17'
                            args '-v $HOME/.m2:/root/.m2'
                        }
                    }
                    environment {
                        DB_URL = 'jdbc:postgresql://postgres:5432/testdb'
                        REDIS_URL = 'redis://redis:6379'
                    }
                    steps {
                        script {
                            // Start test containers
                            sh 'docker-compose -f docker-compose.test.yml up -d'

                            // Wait for services
                            sh './wait-for-it.sh postgres:5432 --timeout=30'
                            sh './wait-for-it.sh redis:6379 --timeout=30'

                            // Run integration tests
                            sh 'mvn verify -Dit.test=*IT -DskipTests'

                            // Check results
                            def integrationResults = junit 'target/failsafe-reports/*.xml'

                            if (integrationResults.failCount > 0) {
                                error "Integration tests failed: ${integrationResults.failCount} failures"
                            }

                            echo "Integration tests passed: ${integrationResults.totalCount - integrationResults.failCount}/${integrationResults.totalCount}"
                        }
                    }
                    post {
                        always {
                            // Cleanup containers
                            sh 'docker-compose -f docker-compose.test.yml down'

                            // Archive results
                            archiveArtifacts 'target/failsafe-reports/*.xml'
                        }
                    }
                }

                stage('Security Scan') {
                    when {
                        expression { params.RUN_SECURITY_SCAN }
                    }
                    steps {
                        script {
                            // Dependency vulnerability scan
                            sh 'mvn org.owasp:dependency-check-maven:check'

                            // Parse results
                            def vulnerabilities = parseDependencyCheckReport('target/dependency-check-report.xml')

                            // Check against thresholds
                            if (vulnerabilities.critical > MAX_CRITICAL_VULNERABILITIES.toInteger()) {
                                error "Critical vulnerabilities found: ${vulnerabilities.critical}"
                            }

                            if (vulnerabilities.high > MAX_HIGH_VULNERABILITIES.toInteger()) {
                                warn "High vulnerabilities found: ${vulnerabilities.high}"
                            }

                            echo "Security scan completed: ${vulnerabilities.critical} critical, ${vulnerabilities.high} high vulnerabilities"
                        }
                    }
                }
            }
        }

        // Stage 4: UI Tests (parallel execution)
        stage('UI Tests') {
            parallel {
                // Run UI tests in parallel by feature area
                stage('UI - User Management') {
                    steps {
                        script {
                            runUiTests('UserManagementTests')
                        }
                    }
                }

                stage('UI - Product Catalog') {
                    steps {
                        script {
                            runUiTests('ProductCatalogTests')
                        }
                    }
                }

                stage('UI - Shopping Cart') {
                    steps {
                        script {
                            runUiTests('ShoppingCartTests')
                        }
                    }
                }

                stage('UI - Checkout') {
                    steps {
                        script {
                            runUiTests('CheckoutTests')
                        }
                    }
                }
            }
            post {
                always {
                    // Combine UI test reports
                    script {
                        combineUiTestReports()
                    }

                    // Archive artifacts
                    archiveArtifacts 'ui-test-results/**/*'
                }
            }
        }

        // Stage 5: Performance Tests (optional)
        stage('Performance Tests') {
            when {
                expression { params.RUN_PERF_TESTS }
            }
            steps {
                script {
                    // Deploy to performance environment
                    sh './deploy-to-perf.sh'

                    // Run performance tests
                    sh 'jmeter -n -t performance/load-test.jmx -l performance/results.jtl'

                    // Analyze results
                    def perfResults = analyzePerformanceResults('performance/results.jtl')

                    // Check thresholds
                    if (perfResults.p95 > P95_RESPONSE_TIME.toInteger()) {
                        warn "P95 response time ${perfResults.p95}ms exceeds threshold ${P95_RESPONSE_TIME}ms"
                    }

                    if (perfResults.errorRate > MAX_ERROR_RATE.toInteger()) {
                        warn "Error rate ${perfResults.errorRate}% exceeds threshold ${MAX_ERROR_RATE}%"
                    }

                    echo "Performance test completed: P95=${perfResults.p95}ms, Error Rate=${perfResults.errorRate}%"
                }
            }
        }

        // Stage 6: Build and Push Docker Image
        stage('Build Docker Image') {
            steps {
                script {
                    // Build Docker image
                    sh "docker build -t ${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG} ."

                    // Push to registry
                    sh "docker push ${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"

                    echo "Docker image built and pushed: ${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"
                }
            }
        }

        // Stage 7: Deploy to Staging
        stage('Deploy to Staging') {
            when {
                expression { params.DEPLOY_ENV == 'staging' || params.DEPLOY_ENV == 'production' }
            }
            steps {
                script {
                    // Update Kubernetes deployment
                    sh "kubectl set image deployment/staging-${PROJECT_NAME} ${PROJECT_NAME}=${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"

                    // Wait for rollout
                    sh "kubectl rollout status deployment/staging-${PROJECT_NAME}"

                    // Run smoke tests
                    runSmokeTests('staging')

                    echo "Deployed to staging: ${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"
                }
            }
        }

        // Stage 8: Manual Approval for Production
        stage('Approval for Production') {
            when {
                expression { params.DEPLOY_ENV == 'production' }
            }
            steps {
                script {
                    // Manual approval step
                    timeout(time: 1, unit: 'HOURS') {
                        input message: 'Deploy to production?', ok: 'Deploy'
                    }
                }
            }
        }

        // Stage 9: Deploy to Production
        stage('Deploy to Production') {
            when {
                expression { params.DEPLOY_ENV == 'production' }
            }
            steps {
                script {
                    // Canary deployment
                    sh "./canary-deploy.sh ${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"

                    // Monitor canary
                    monitorCanary(5) // Monitor for 5 minutes

                    // Full rollout if canary successful
                    sh "kubectl set image deployment/production-${PROJECT_NAME} ${PROJECT_NAME}=${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"

                    // Wait for rollout
                    sh "kubectl rollout status deployment/production-${PROJECT_NAME}"

                    // Run post-deploy smoke tests
                    runSmokeTests('production')

                    echo "Deployed to production: ${DOCKER_REGISTRY}/${PROJECT_NAME}:${BUILD_TAG}"
                }
            }
        }
    }

    post {
        success {
            script {
                echo "Pipeline ${BUILD_TAG} completed successfully"

                // Send success notification
                slackSend(
                    color: 'good',
                    message: "Pipeline ${BUILD_TAG} succeeded for ${PROJECT_NAME}",
                    channel: '#ci-notifications'
                )
            }
        }
        failure {
            script {
                echo "Pipeline ${BUILD_TAG} failed"

                // Send failure notification
                slackSend(
                    color: 'danger',
                    message: "Pipeline ${BUILD_TAG} failed for ${PROJECT_NAME}. See ${env.BUILD_URL}",
                    channel: '#ci-notifications'
                )

                // Create bug report
                createBugReport()
            }
        }
        aborted {
            script {
                echo "Pipeline ${BUILD_TAG} was aborted"

                // Send aborted notification
                slackSend(
                    color: 'warning',
                    message: "Pipeline ${BUILD_TAG} was aborted for ${PROJECT_NAME}",
                    channel: '#ci-notifications'
                )
            }
        }
        always {
            // Clean workspace
            cleanWs()

            // Update build status
            updateBuildStatus()
        }
    }
}

// Helper functions
void runUiTests(String testSuite) {
    // Run UI tests with Selenium/Playwright
    sh "mvn test -Dtest=${testSuite} -Dbrowser=headless"

    // Archive screenshots on failure
    sh "tar -czf ui-screenshots-${testSuite}.tar.gz screenshots/"
    archiveArtifacts "ui-screenshots-${testSuite}.tar.gz"
}

void runSmokeTests(String environment) {
    // Run smoke tests against environment
    sh "mvn test -Dtest=SmokeTest -Denvironment=${environment}"

    def smokeResults = junit 'target/surefire-reports/*.xml'

    if (smokeResults.failCount > 0) {
        error "Smoke tests failed in ${environment}: ${smokeResults.failCount} failures"
    }
}

void monitorCanary(int minutes) {
    // Monitor canary deployment metrics
    for (int i = 0; i < minutes; i++) {
        sleep 60  // Wait 1 minute

        // Check canary metrics
        def metrics = getCanaryMetrics()

        if (metrics.errorRate > 5) {  // 5% error rate threshold
            error "Canary deployment failing: ${metrics.errorRate}% error rate"

            // Rollback canary
            sh "./rollback-canary.sh"
            break
        }
    }
}

import java.time.LocalDate;
import java.util.UUID;
import java.util.List;
import java.util.ArrayList;

/**
 * Test Data Factory for creating consistent, realistic test data
 * This ensures tests have reliable data without external dependencies
 */
public class TestDataFactory {

    private static int userCounter = 1;
    private static int productCounter = 1;
    private static int orderCounter = 1;

    /**
     * Create a test user with realistic data
     */
    public static User createUser() {
        return createUser("testuser" + userCounter++);
    }

    public static User createUser(String username) {
        User user = new User();
        user.setId(UUID.randomUUID().toString());
        user.setUsername(username);
        user.setEmail(username + "@example.com");
        user.setFirstName("Test");
        user.setLastName("User" + userCounter);
        user.setPassword("Password123!");
        user.setActive(true);
        user.setCreatedDate(LocalDate.now());
        return user;
    }

    /**
     * Create a test product
     */
    public static Product createProduct() {
        return createProduct("Product " + productCounter++, 99.99);
    }

    public static Product createProduct(String name, double price) {
        Product product = new Product();
        product.setId(UUID.randomUUID().toString());
        product.setName(name);
        product.setDescription("Test product description");
        product.setPrice(price);
        product.setSku("SKU-" + System.currentTimeMillis());
        product.setInStock(true);
        product.setCategory("Test Category");
        return product;
    }

    /**
     * Create a test order with items
     */
    public static Order createOrder(User user, List<Product> products) {
        Order order = new Order();
        order.setId(UUID.randomUUID().toString());
        order.setUserId(user.getId());
        order.setOrderNumber("ORD-" + orderCounter++);
        order.setOrderDate(LocalDate.now());
        order.setStatus("PENDING");

        List<OrderItem> items = new ArrayList<>();
        double total = 0.0;

        for (int i = 0; i < products.size(); i++) {
            Product product = products.get(i);
            OrderItem item = new OrderItem();
            item.setProductId(product.getId());
            item.setQuantity(i + 1);
            item.setUnitPrice(product.getPrice());
            items.add(item);
            total += product.getPrice() * (i + 1);
        }

        order.setItems(items);
        order.setTotalAmount(total);
        return order;
    }

    /**
     * Create test data for a complete shopping scenario
     */
    public static ShoppingScenario createShoppingScenario() {
        // Create user
        User user = createUser();

        // Create products
        List<Product> products = new ArrayList<>();
        products.add(createProduct("Laptop", 1299.99));
        products.add(createProduct("Mouse", 29.99));
        products.add(createProduct("Keyboard", 89.99));

        // Create cart
        ShoppingCart cart = new ShoppingCart();
        cart.setUserId(user.getId());
        cart.setItems(products.stream()
            .map(p -> new CartItem(p.getId(), 1, p.getPrice()))
            .toList());

        // Create order
        Order order = createOrder(user, products);

        return new ShoppingScenario(user, products, cart, order);
    }

    /**
     * Builder for creating complex test objects
     */
    public static class UserBuilder {
        private User user = new User();

        public UserBuilder withId(String id) {
            user.setId(id);
            return this;
        }

        public UserBuilder withUsername(String username) {
            user.setUsername(username);
            return this;
        }

        public UserBuilder withEmail(String email) {
            user.setEmail(email);
            return this;
        }

        public UserBuilder active(boolean active) {
            user.setActive(active);
            return this;
        }

        public User build() {
            // Set defaults for any missing required fields
            if (user.getId() == null) {
                user.setId(UUID.randomUUID().toString());
            }
            if (user.getUsername() == null) {
                user.setUsername("user" + System.currentTimeMillis());
            }
            if (user.getEmail() == null) {
                user.setEmail(user.getUsername() + "@example.com");
            }
            return user;
        }
    }

    /**
     * Helper method to create unique test data for parallel execution
     */
    public static String uniqueIdentifier(String prefix) {
        return prefix + "_" + Thread.currentThread().getId() + "_" + System.currentTimeMillis();
    }
}

/**
 * Example test using the test data factory
 */
class UserRegistrationTest {

    @Test
    void testUserRegistration() {
        // Arrange: Create test data
        User testUser = TestDataFactory.createUser();

        // Or use builder for more control
        User specificUser = new TestDataFactory.UserBuilder()
            .withUsername("johndoe")
            .withEmail("john.doe@example.com")
            .active(true)
            .build();

        // Act: Execute test
        UserService userService = new UserService();
        User registeredUser = userService.register(specificUser);

        // Assert: Verify results
        assertNotNull(registeredUser.getId());
        assertEquals("johndoe", registeredUser.getUsername());
        assertTrue(registeredUser.isActive());
    }

    @Test
    void testCompleteShoppingFlow() {
        // Create complete test scenario
        ShoppingScenario scenario = TestDataFactory.createShoppingScenario();

        // Execute and test complete flow
        OrderService orderService = new OrderService();
        Order completedOrder = orderService.processOrder(
            scenario.getUser(), 
            scenario.getCart()
        );

        assertEquals("COMPLETED", completedOrder.getStatus());
        assertTrue(completedOrder.getTotalAmount() > 0);
    }
}

# main.tf - Example Terraform module with testing considerations

# Security-focused S3 bucket configuration
resource "aws_s3_bucket" "secure_data" {
  bucket = "${var.bucket_prefix}-secure-data"

  # Security best practices
  versioning {
    enabled = true  # Enable versioning for recovery
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"  # Encrypt data at rest
      }
    }
  }

  # Access logging for audit trail
  logging {
    target_bucket = aws_s3_bucket.logs.id
    target_prefix = "log/"
  }

  # Lifecycle policies for cost optimization
  lifecycle_rule {
    id      = "archive_old_data"
    enabled = true

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    transition {
      days          = 90
      storage_class = "GLACIER"
    }

    expiration {
      days = 365
    }
  }

  # Tags for cost allocation and management
  tags = {
    Name        = "Secure Data Bucket"
    Environment = var.environment
    Owner       = var.team_name
    CostCenter  = var.cost_center
    Compliance  = "GDPR"
  }
}

# Security group with least privilege principle
resource "aws_security_group" "app_security" {
  name        = "app-security-group"
  description = "Security group for application servers"
  vpc_id      = var.vpc_id

  # Ingress rules - only necessary ports
  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP from load balancer"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.lb_security.id]
  }

  ingress {
    description = "SSH from bastion"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    security_groups = [aws_security_group.bastion_security.id]
  }

  # Egress rules - restrict outbound traffic
  egress {
    description = "Outbound to internet"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# IAM role with least privilege
resource "aws_iam_role" "app_role" {
  name = "app-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "App Execution Role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "app_policy" {
  name = "app-execution-policy"
  role = aws_iam_role.app_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.secure_data.arn,
          "${aws_s3_bucket.secure_data.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

package test

import (
	"testing"
	"time"
	"fmt"
	"github.com/gruntwork-io/terratest/modules/terraform"
	"github.com/gruntwork-io/terratest/modules/aws"
	"github.com/gruntwork-io/terratest/modules/http-helper"
	"github.com/stretchr/testify/assert"
)

func TestTerraformWebserver(t *testing.T) {
	t.Parallel()

	// Generate a unique identifier for this test run
	testID := fmt.Sprintf("test-%d", time.Now().UnixNano())

	// Terraform options with test-specific variables
	terraformOptions := &terraform.Options{
		// Set the path to the Terraform code
		TerraformDir: "../examples/webserver",

		// Variables to pass to Terraform
		Vars: map[string]interface{}{
			"environment": "test",
			"instance_type": "t3.micro",
			"instance_name": fmt.Sprintf("webserver-%s", testID),
			"test_mode": true,
		},

		// Environment variables for AWS provider
		EnvVars: map[string]string{
			"AWS_DEFAULT_REGION": "us-east-1",
		},

		// Enable retryable errors
		MaxRetries: 3,
		TimeBetweenRetries: 5 * time.Second,

		// Set up to retry on specific errors
		RetryableTerraformErrors: map[string]string{
			".*": "Retry all errors for tests",
		},
	}

	// Clean up resources after test completes
	defer terraform.Destroy(t, terraformOptions)

	// Deploy the infrastructure
	terraform.InitAndApply(t, terraformOptions)

	// Get outputs from Terraform
	instanceID := terraform.Output(t, terraformOptions, "instance_id")
	publicIP := terraform.Output(t, terraformOptions, "public_ip")
	vpcID := terraform.Output(t, terraformOptions, "vpc_id")

	// Test 1: Verify EC2 instance is running
	t.Run("Instance should be running", func(t *testing.T) {
		// Wait for instance to be running
		aws.WaitForEc2InstanceRunning(t, "us-east-1", instanceID, 10, 30*time.Second)

		// Get instance details
		instance := aws.GetEc2Instance(t, "us-east-1", instanceID)

		// Assertions
		assert.Equal(t, "running", *instance.State.Name)
		assert.Equal(t, "t3.micro", *instance.InstanceType)
		assert.NotNil(t, instance.PublicIpAddress)
	})

	// Test 2: Verify security group configuration
	t.Run("Security group should have correct rules", func(t *testing.T) {
		// Get security group ID from instance
		sgID := aws.GetSecurityGroupsForInstance(t, "us-east-1", instanceID)[0]

		// Get security group rules
		rules := aws.GetSecurityGroupRules(t, "us-east-1", sgID)

		// Verify only necessary ports are open
		openPorts := []int64{}
		for _, rule := range rules {
			if rule.IsEgress == false && rule.FromPort != nil {
				openPorts = append(openPorts, *rule.FromPort)
			}
		}

		// Should only have ports 22 (SSH) and 80 (HTTP) open
		assert.ElementsMatch(t, []int64{22, 80}, openPorts)
	})

	// Test 3: Verify web server is responding
	t.Run("Web server should respond correctly", func(t *testing.T) {
		url := fmt.Sprintf("http://%s", publicIP)

		// Retry HTTP request with exponential backoff
		http_helper.HttpGetWithRetryWithCustomValidation(
			t,
			url,
			nil,
			10,               // max retries
			5 * time.Second, // time between retries
			func(statusCode int, body string) bool {
				// Validate response
				return statusCode == 200 && 
					   len(body) > 0 && 
					   (body == "Hello World" || 
					    body == "Welcome to the test server")
			},
		)
	})

	// Test 4: Verify tags are applied correctly
	t.Run("Resources should have correct tags", func(t *testing.T) {
		// Get instance tags
		tags := aws.GetTagsForEc2Instance(t, "us-east-1", instanceID)

		// Required tags
		requiredTags := map[string]string{
			"Environment": "test",
			"Name": fmt.Sprintf("webserver-%s", testID),
			"ManagedBy": "Terraform",
			"TestRun": testID,
		}

		// Verify all required tags are present
		for key, expectedValue := range requiredTags {
			actualValue, exists := tags[key]
			assert.True(t, exists, "Missing tag: %s", key)
			assert.Equal(t, expectedValue, actualValue, "Incorrect value for tag: %s", key)
		}
	})

	// Test 5: Verify VPC configuration
	t.Run("VPC should have correct configuration", func(t *testing.T) {
		vpc := aws.GetVpcById(t, "us-east-1", vpcID)

		// Check CIDR block
		assert.Equal(t, "10.0.0.0/16", *vpc.CidrBlock)

		// Check DNS settings
		assert.True(t, *vpc.EnableDnsSupport)
		assert.True(t, *vpc.EnableDnsHostnames)
	})

	// Test 6: Cleanup verification (implicit through defer)
	t.Log("All integration tests passed. Resources will be cleaned up.")
}

// Helper function for testing module outputs
func TestTerraformModuleOutputs(t *testing.T) {
	t.Parallel()

	terraformOptions := &terraform.Options{
		TerraformDir: "../modules/vpc",
		Vars: map[string]interface{}{
			"cidr_block": "10.0.0.0/16",
			"environment": "test",
		},
	}

	// Test module outputs without applying
	outputs := terraform.OutputAll(t, terraformOptions)

	// Verify outputs exist
	assert.Contains(t, outputs, "vpc_id")
	assert.Contains(t, outputs, "public_subnet_ids")
	assert.Contains(t, outputs, "private_subnet_ids")
	assert.Contains(t, outputs, "nat_gateway_ids")

	// Verify output types
	vpcID := outputs["vpc_id"].(string)
	assert.NotEmpty(t, vpcID)
	assert.Regexp(t, "^vpc-[a-z0-9]+", vpcID)
}

