package kubernetes.security

# Deny containers running as root
default allow_container = true

allow_container = false {
    container := input.spec.containers[_]
    container.securityContext.runAsUser == 0
}

violation[msg] {
    container := input.spec.containers[_]
    container.securityContext.runAsUser == 0
    msg := sprintf("Container %s must not run as root (runAsUser: 0)", [container.name])
}

# Require read-only root filesystem
default require_readonly_root = false

require_readonly_root = true {
    container := input.spec.containers[_]
    container.securityContext.readOnlyRootFilesystem == true
}

violation[msg] {
    container := input.spec.containers[_]
    not container.securityContext.readOnlyRootFilesystem
    msg := sprintf("Container %s must have readOnlyRootFilesystem: true", [container.name])
}

# Require resource limits
default require_resource_limits = false

require_resource_limits = true {
    container := input.spec.containers[_]
    container.resources.limits.cpu
    container.resources.limits.memory
}

violation[msg] {
    container := input.spec.containers[_]
    not container.resources.limits.cpu
    msg := sprintf("Container %s must have CPU limits", [container.name])
}

violation[msg] {
    container := input.spec.containers[_]
    not container.resources.limits.memory
    msg := sprintf("Container %s must have memory limits", [container.name])
}

# Deny privileged containers
default deny_privileged = true

deny_privileged = false {
    container := input.spec.containers[_]
    container.securityContext.privileged == true
}

violation[msg] {
    container := input.spec.containers[_]
    container.securityContext.privileged == true
    msg := sprintf("Container %s must not run in privileged mode", [container.name])
}

# Require liveness and readiness probes
default require_probes = false

require_probes = true {
    container := input.spec.containers[_]
    container.livenessProbe
    container.readinessProbe
}

violation[msg] {
    container := input.spec.containers[_]
    not container.livenessProbe
    msg := sprintf("Container %s must have a liveness probe", [container.name])
}

violation[msg] {
    container := input.spec.containers[_]
    not container.readinessProbe
    msg := sprintf("Container %s must have a readiness probe", [container.name])
}

